//! Generated by `scope-watch` (R170). Not written by hand: generate it
//! again instead of editing it. It notes what the holders of a value read
//! when a function is entered and when it is left, and writes each new
//! combination once per process.
#![allow(clippy::all, unused)]

use std::collections::BTreeSet;
use std::io::Write as _;
use std::sync::Mutex;

type Noted = (&'static str, &'static str, Vec<u8>, Vec<u8>);

static SEEN: Mutex<BTreeSet<Noted>> = Mutex::new(BTreeSet::new());

/// Lives from the start of a function to its end.
pub(crate) struct Watch {
    of: &'static str,
    at: &'static str,
    value: *const (),
    read: fn(*const ()) -> Vec<u8>,
    before: Vec<u8>,
}

impl Watch {
    /// `value` must stay where it is for as long as the watch lives: the
    /// generated statements pass only what the function took by reference.
    pub(crate) fn new(of: &'static str, at: &'static str, value: *const (), read: fn(*const ()) -> Vec<u8>) -> Self {
        Self { of, at, value, read, before: read(value) }
    }
}

impl Drop for Watch {
    fn drop(&mut self) {
        let after = (self.read)(self.value);
        let noted: Noted = (self.of, self.at, std::mem::take(&mut self.before), after);
        let mut seen = SEEN.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
        if seen.contains(&noted) {
            return;
        }
        if let Ok(directory) = std::env::var("LESSCODE_WATCH_OUT") {
            let thread = std::thread::current();
            let line = format!("{}\t{}\t{:?}\t{:?}\t{}\n", noted.0, noted.1, noted.2, noted.3, thread.name().unwrap_or("(another thread)"));
            let path = std::path::Path::new(&directory).join(format!("{}.tsv", std::process::id()));
            if let Ok(mut file) = std::fs::OpenOptions::new().create(true).append(true).open(path) {
                let _ = file.write_all(line.as_bytes());
            }
        }
        seen.insert(noted);
    }
}
